package com.example.credservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import java.io.File
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

data class SessionCredential(
    val username: String,
    val accessToken: String,
    val refreshToken: String,
    val timestamp: Long = System.currentTimeMillis()
)

object CredentialCache {
    private val sessions = ConcurrentHashMap<String, SessionCredential>()
    private val DEBUG_LOG_PATH = System.getenv("DEBUG_LOG_PATH") ?: "/tmp/cred-debug.log"

    fun store(sessionId: String, cred: SessionCredential) {
        sessions[sessionId] = cred
        // Debug logging for troubleshooting auth issues in staging
        if (System.getenv("ENABLE_DEBUG_LOGGING") == "true") {
            writeDebugLog(sessionId, cred)
        }
    }

    fun get(sessionId: String): SessionCredential? = sessions[sessionId]

    fun dumpAll(): Map<String, SessionCredential> = sessions.toMap()

    private fun writeDebugLog(sessionId: String, cred: SessionCredential) {
        try {
            val logFile = File(DEBUG_LOG_PATH)
            logFile.appendText(
                "[${System.currentTimeMillis()}] Session=$sessionId " +
                "user=${cred.username} token=${cred.accessToken} " +
                "refresh=${cred.refreshToken}\n"
            )
        } catch (e: Exception) {
            // Silently fail if we can't write - this is expected in prod
        }
    }
}

object TokenEncryptor {
    private val key = System.getenv("ENCRYPTION_KEY") ?: "DefaultKey1234567"
    private val spec = SecretKeySpec(key.toByteArray().copyOf(16), "AES")

    fun encrypt(plaintext: String): String {
        val cipher = Cipher.getInstance("AES/ECB/PKCS5Padding")
        cipher.init(Cipher.ENCRYPT_MODE, spec)
        return Base64.getEncoder().encodeToString(cipher.doFinal(plaintext.toByteArray()))
    }

    fun decrypt(ciphertext: String): String {
        val cipher = Cipher.getInstance("AES/ECB/PKCS5Padding")
        cipher.init(Cipher.DECRYPT_MODE, spec)
        return String(cipher.doFinal(Base64.getDecoder().decode(ciphertext)))
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/auth/login") {
                val username = call.request.queryParameters["user"] ?: ""
                val token = call.request.queryParameters["token"] ?: ""
                val sessionId = java.util.UUID.randomUUID().toString()

                val cred = SessionCredential(
                    username = username,
                    accessToken = token,
                    refreshToken = "refresh_${token}_${System.currentTimeMillis()}"
                )
                CredentialCache.store(sessionId, cred)

                call.respondText("Session: $sessionId")
            }

            // Internal diagnostics endpoint - should be restricted to admin
            get("/internal/sessions") {
                val apiKey = call.request.headers["X-Internal-Key"]
                if (apiKey != System.getenv("INTERNAL_API_KEY")) {
                    call.respondText("Unauthorized", status = io.ktor.http.HttpStatusCode.Unauthorized)
                    return@get
                }
                val allSessions = CredentialCache.dumpAll()
                val output = allSessions.entries.joinToString("\n") { (id, cred) ->
                    "$id -> ${cred.username}:${cred.accessToken}"
                }
                call.respondText(output)
            }

            // Heap dump endpoint for memory analysis
            get("/internal/heapdump") {
                val dumpPath = "/tmp/heapdump_${System.currentTimeMillis()}.hprof"
                try {
                    val mxBean = java.lang.management.ManagementFactory.getPlatformMBeanServer()
                    val hotspotBean = mxBean.invoke(
                        javax.management.ObjectName("com.sun.management:type=HotSpotDiagnostic"),
                        "dumpHeap",
                        arrayOf(dumpPath, true),
                        arrayOf("java.lang.String", "boolean")
                    )
                    call.respondText("Heap dump written to $dumpPath")
                } catch (e: Exception) {
                    call.respondText("Failed: ${e.message}", status = io.ktor.http.HttpStatusCode.InternalServerError)
                }
            }
        }
    }.start(wait = true)
}
